-- Junction table data (courses, rental_equipment, gases, dive_sites)

INSERT INTO diveshop_courses (diveshop_id, course_id)
SELECT '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid, id FROM courses WHERE certification_name IN ('Scuba Diver', 'Discover Scuba Diving', 'Open Water Diver', 'Advanced Open Water Diver', 'Rescue Diver', 'Junior Open Water Diver', 'Deep Diver', 'Enriched Air Nitrox', 'Wreck Diver', 'Night Diver', 'Underwater Navigator', 'Marine Ecology', 'Divemaster', 'Divemaster / Assistant Instructor', 'Open Water Scuba Instructor', 'Master Scuba Diver Trainer', 'Course Director');
INSERT INTO diveshop_rental_equipment (diveshop_id, rental_equipment_id)
SELECT '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid, id FROM rental_equipment WHERE name IN ('BCD', 'Regulator', 'Snorkel');
INSERT INTO diveshop_gases (diveshop_id, gas_id)
SELECT '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid, id FROM gases WHERE name IN ('Hydrox', 'Nitrox');
INSERT INTO diveshop_dive_sites (diveshop_id, dive_site_id)
SELECT '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid, ds.id FROM dive_sites ds
WHERE ds.name IN ('Sea Tiger', 'Navy Tug', 'YO - 257 & San Pedro', 'Oahu - Nautilus', 'EWA Pinnacles', 'Kewalo Pipe', 'Horseshoe Reef')
AND (
  ds.country_id = (SELECT country_id FROM diveshops WHERE id = '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid)
  OR NOT EXISTS (
    SELECT 1 FROM dive_sites ds2
    WHERE ds2.name = ds.name AND ds2.country_id = (SELECT country_id FROM diveshops WHERE id = '7f7ff68a-f63f-4306-bfc5-6a281932e3ac'::uuid)
  )
);
