INSERT INTO diveshop_rental_equipment (diveshop_id, rental_equipment_id)
SELECT '231a642a-3e90-47d2-ae42-58edc06701e9'::uuid, id FROM rental_equipment WHERE name IN ('Yes (unspecified gear)');
INSERT INTO diveshop_dive_sites (diveshop_id, dive_site_id)
SELECT '231a642a-3e90-47d2-ae42-58edc06701e9'::uuid, ds.id FROM dive_sites ds
WHERE ds.name IN ('Puri Jati', 'Menjangan Island - POS II', 'Manta Point', 'USAT Liberty Wreck')
AND (
  ds.country_id = (SELECT country_id FROM diveshops WHERE id = '231a642a-3e90-47d2-ae42-58edc06701e9'::uuid)
  OR NOT EXISTS (
    SELECT 1 FROM dive_sites ds2
    WHERE ds2.name = ds.name AND ds2.country_id = (SELECT country_id FROM diveshops WHERE id = '231a642a-3e90-47d2-ae42-58edc06701e9'::uuid)
  )
);